1126: LogicalResult AxisInfoAnalysis::visitOperation(
1127:     Operation *op, ArrayRef<const dataflow::Lattice<AxisInfo> *> operands,
1128:     ArrayRef<dataflow::Lattice<AxisInfo> *> results) {
1129:   // If any operands are not yet ready, skip this operation for now.
1130:   for (auto op : operands)
1131:     if (op->getValue().getRank() == 0)
1132:       return success();
1133:   AxisInfo curr = visitors.apply(op, operands);
1134:   if (curr.getRank() == 0) {
1135:     setAllToEntryStates(results);
1136:     return success();
1137:   }
1138:   // override with hint
1139:   auto newContiguity = curr.getContiguity();
1140:   auto newDivisibility = curr.getDivisibility();
1141:   auto newConstancy = curr.getConstancy();
1142:   AxisInfo::initDimVectorFromHint(op->getDiscardableAttr("tt.contiguity"),
1143:                                   &newContiguity);
1144:   AxisInfo::initDimVectorFromHint(op->getDiscardableAttr("tt.divisibility"),
1145:                                   &newDivisibility);
1146:   AxisInfo::initDimVectorFromHint(op->getDiscardableAttr("tt.constancy"),
1147:                                   &newConstancy);
1148:   curr = AxisInfo(newContiguity, newDivisibility, newConstancy,
1149:                   curr.getConstantValue());
1150:   // join all lattice elements
1151:   for (auto *result : results)
1152:     propagateIfChanged(result, result->join(curr));
1153:   return success();
1154: }
