1196: void AxisInfo::initDimVectorFromHint(Attribute attr, DimVectorT *vec) {
1197:   if (auto int_attr = dyn_cast_or_null<IntegerAttr>(attr))
1198:     *vec = DimVectorT(1, int_attr.getValue().getZExtValue());
1199:   if (auto dense_attr = dyn_cast_or_null<DenseElementsAttr>(attr)) {
1200:     auto vals = dense_attr.getValues<int>();
1201:     *vec = DimVectorT(vals.begin(), vals.end());
1202:   }
1203: }

1275: unsigned ModuleAxisInfoAnalysis::getContiguity(Value offsetsValue,
1276:                                                unsigned elementBitWidth) {
1277:   // FIXME: This is not as good as it could be, as we don't need to restrict
1278:   // the analysis to one dimension. We should determine contiguity on the
1279:   // flattenOuts() layout
1280:   auto tensorTy = cast<RankedTensorType>(offsetsValue.getType());
1281:   auto linAttr = gpu::toLinearEncoding(tensorTy);
1282:   auto order = linAttr.getOrder();
1283:   unsigned align = getAlignment(offsetsValue, elementBitWidth);
1284: 
1285:   auto uniqueContigPerThread = linAttr.getContigPerThread();
1286:   assert(order[0] < uniqueContigPerThread.size() &&
1287:          "Unexpected uniqueContigPerThread size");
1288:   unsigned contiguity = uniqueContigPerThread[order[0]];
1289:   LDBG("getContiguity uniqueContigPerThread = " << contiguity);
1290:   contiguity = std::min(align, contiguity);
1291: 
1292:   return contiguity;
1293: }

1308: unsigned ModuleAxisInfoAnalysis::getAlignment(Value offsetsValue,
1309:                                               unsigned elementBitWidth) {
1310:   auto tensorTy = cast<RankedTensorType>(offsetsValue.getType());
1311:   auto *axisInfo = getAxisInfo(offsetsValue);
1312:   if (!axisInfo)
1313:     return 1;
1314:   auto linAttr = gpu::toLinearEncoding(tensorTy);
1315:   auto order = linAttr.getOrder();
1316: 
1317:   auto divisibility = axisInfo->getDivisibility(order[0]);
1318:   auto elemNumBytes = std::max<unsigned>(elementBitWidth / 8, 1);
1319:   auto elemTy = tensorTy.getElementType();
1320:   auto maxMultiple = isa<PointerType>(elemTy)
1321:                          ? std::max<int64_t>(divisibility / elemNumBytes, 1)
1322:                          : divisibility;
1323: 
1324:   auto maxContig = axisInfo->getContiguity(order[0]);
1325:   unsigned alignment = std::min(maxMultiple, maxContig);
1326:   LDBG("getAlignment order[0] " << order[0] << " maxContig = " << maxContig
1327:                                 << " elemNumBits = " << elementBitWidth
1328:                                 << " maxMultiple = " << maxMultiple
1329:                                 << " alignment " << alignment);
1330:   LLVM_DEBUG({
1331:     std::string axisStr;
1332:     llvm::raw_string_ostream os(axisStr);
1333:     axisInfo->print(os);
1334:     LDBG("-- " << axisStr);
1335:   });
1336:   return alignment;
